[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #2563EB;
      --primary-dark: #1D4ED8;
      --primary-light: #DBEAFE;
      --primary-50: #EFF6FF;
      --accent: #059669;
      --accent-dark: #047857;
      --accent-light: #D1FAE5;
      --bg-white: #FFFFFF;
      --bg-light: #F8FAFC;
      --bg-section: #F1F5F9;
      --text-primary: #1E293B;
      --text-secondary: #475569;
      --text-muted: #64748B;
      --border: #E2E8F0;
      --border-light: #F1F5F9;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--text-primary);
      background: var(--bg-white);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
      html { scroll-behavior: auto; }
    }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    a { color: var(--primary); text-decoration: none; transition: color var(--transition); }
    a:hover { color: var(--primary-dark); }

    /* Skip link */
    .skip-link {
      position: absolute; top: -100%; left: 16px; z-index: 10000;
      background: var(--primary); color: #fff; padding: 8px 16px; border-radius: var(--radius-sm);
      font-weight: 600; font-size: 14px;
    }
    .skip-link:focus { top: 16px; }

    /* ===== HEADER ===== */
    .header {
      position: sticky; top: 0; z-index: 1000;
      background: rgba(255,255,255,0.95); backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-light);
      transition: box-shadow var(--transition);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 72px;
    }
    .logo { display: flex; align-items: center; gap: 10px; font-size: 22px; font-weight: 800; color: var(--primary); cursor: pointer; }
    .logo svg { width: 36px; height: 36px; }
    .logo:hover { color: var(--primary-dark); }

    .nav-links { display: flex; align-items: center; gap: 8px; }
    .nav-links a {
      padding: 8px 16px; border-radius: var(--radius-sm);
      font-size: 15px; font-weight: 500; color: var(--text-secondary);
      transition: background var(--transition), color var(--transition);
    }
    .nav-links a:hover { background: var(--primary-50); color: var(--primary); }
    .nav-links .btn-login {
      color: var(--primary); font-weight: 600;
    }
    .nav-links .btn-signup {
      background: var(--primary); color: #fff; font-weight: 600;
      padding: 10px 20px;
    }
    .nav-links .btn-signup:hover { background: var(--primary-dark); color: #fff; }

    .hamburger {
      display: none; background: none; border: none; cursor: pointer;
      padding: 8px; border-radius: var(--radius-sm);
    }
    .hamburger:hover { background: var(--primary-50); }
    .hamburger svg { width: 24px; height: 24px; color: var(--text-primary); }

    /* Mobile drawer */
    .mobile-drawer {
      position: fixed; top: 0; right: -300px; width: 300px; height: 100vh;
      background: #fff; z-index: 10001; padding: 24px;
      box-shadow: var(--shadow-xl);
      transition: right 300ms ease-out;
    }
    .mobile-drawer.open { right: 0; }
    .drawer-overlay {
      position: fixed; inset: 0; background: rgba(0,0,0,0.4);
      z-index: 10000; opacity: 0; pointer-events: none;
      transition: opacity var(--transition);
    }
    .drawer-overlay.open { opacity: 1; pointer-events: auto; }
    .drawer-close {
      background: none; border: none; cursor: pointer; padding: 8px;
      border-radius: var(--radius-sm); margin-left: auto; display: block;
    }
    .drawer-close:hover { background: var(--bg-section); }
    .drawer-close svg { width: 24px; height: 24px; color: var(--text-primary); }
    .drawer-nav { margin-top: 32px; display: flex; flex-direction: column; gap: 4px; }
    .drawer-nav a {
      padding: 14px 16px; border-radius: var(--radius-sm);
      font-size: 17px; font-weight: 500; color: var(--text-secondary);
      display: block;
    }
    .drawer-nav a:hover { background: var(--primary-50); color: var(--primary); }
    .drawer-nav .btn-signup-mobile {
      background: var(--primary); color: #fff; text-align: center;
      margin-top: 16px; font-weight: 600;
    }
    .drawer-nav .btn-signup-mobile:hover { background: var(--primary-dark); color: #fff; }

    /* ===== HERO ===== */
    .hero {
      background: linear-gradient(135deg, var(--primary-50) 0%, #EFF6FF 30%, #FFFFFF 70%, var(--accent-light) 100%);
      padding: 80px 0 96px;
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; top: -120px; right: -80px;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(37,99,235,0.06) 0%, transparent 70%);
    }
    .hero::after {
      content: ''; position: absolute; bottom: -60px; left: -40px;
      width: 300px; height: 300px; border-radius: 50%;
      background: radial-gradient(circle, rgba(5,150,105,0.05) 0%, transparent 70%);
    }
    .hero-content { position: relative; z-index: 1; text-align: center; max-width: 780px; margin: 0 auto; }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--accent-light); color: var(--accent-dark);
      padding: 8px 16px; border-radius: 100px; font-size: 14px; font-weight: 600;
      margin-bottom: 24px;
    }
    .hero-badge svg { width: 16px; height: 16px; }
    .hero h1 {
      font-size: clamp(36px, 5vw, 56px); font-weight: 800;
      line-height: 1.1; color: var(--text-primary);
      margin-bottom: 20px; letter-spacing: -0.02em;
    }
    .hero p {
      font-size: 18px; line-height: 1.7; color: var(--text-secondary);
      max-width: 600px; margin: 0 auto 40px;
    }

    /* Search bar */
    .search-bar {
      background: #fff; border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl); padding: 8px;
      max-width: 720px; margin: 0 auto;
      border: 1px solid var(--border);
      position: relative;
    }
    .search-fields {
      display: flex; align-items: center; gap: 4px;
    }
    .search-field {
      flex: 1; position: relative;
    }
    .search-field input,
    .search-field select {
      width: 100%; padding: 14px 16px 14px 44px;
      border: none; border-radius: var(--radius-md);
      font-size: 15px; font-family: inherit; color: var(--text-primary);
      background: var(--bg-light); outline: none;
      transition: background var(--transition), box-shadow var(--transition);
      -webkit-appearance: none;
    }
    .search-field input::placeholder { color: var(--text-muted); }
    .search-field input:focus,
    .search-field select:focus {
      background: #fff; box-shadow: 0 0 0 2px var(--primary-light);
    }
    .search-field .field-icon {
      position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
      width: 20px; height: 20px; color: var(--text-muted); pointer-events: none;
    }
    .search-field select { cursor: pointer; }
    .search-field .select-chevron {
      position: absolute; right: 12px; top: 50%; transform: translateY(-50%);
      width: 16px; height: 16px; color: var(--text-muted); pointer-events: none;
    }
    .search-btn {
      background: var(--primary); color: #fff; border: none;
      padding: 14px 28px; border-radius: var(--radius-md);
      font-size: 16px; font-weight: 600; font-family: inherit;
      cursor: pointer; white-space: nowrap;
      display: flex; align-items: center; gap: 8px;
      transition: background var(--transition), transform 150ms ease;
    }
    .search-btn:hover { background: var(--primary-dark); }
    .search-btn:active { transform: scale(0.97); }
    .search-btn svg { width: 20px; height: 20px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute; top: 100%; left: 0; right: 0;
      background: #fff; border-radius: var(--radius-md);
      box-shadow: var(--shadow-xl); border: 1px solid var(--border);
      margin-top: 4px; z-index: 100;
      max-height: 280px; overflow-y: auto;
      display: none;
    }
    .autocomplete-dropdown.visible { display: block; }
    .autocomplete-item {
      padding: 12px 16px; cursor: pointer;
      display: flex; align-items: center; gap: 12px;
      font-size: 15px; color: var(--text-secondary);
      transition: background var(--transition);
    }
    .autocomplete-item:hover,
    .autocomplete-item.highlighted { background: var(--primary-50); color: var(--primary); }
    .autocomplete-item svg { width: 18px; height: 18px; flex-shrink: 0; color: var(--text-muted); }
    .autocomplete-item .match { font-weight: 600; color: var(--primary); }
    .autocomplete-category {
      padding: 8px 16px; font-size: 12px; font-weight: 600;
      color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em;
      border-top: 1px solid var(--border-light);
    }
    .autocomplete-category:first-child { border-top: none; }

    /* ===== STATS ===== */
    .stats {
      background: var(--bg-white); padding: 56px 0;
      border-bottom: 1px solid var(--border-light);
    }
    .stats-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;
      text-align: center;
    }
    .stat-item { padding: 16px; }
    .stat-number {
      font-size: clamp(28px, 3vw, 40px); font-weight: 800;
      color: var(--primary); line-height: 1.2;
    }
    .stat-label {
      font-size: 15px; color: var(--text-muted); margin-top: 4px;
      font-weight: 500;
    }

    /* ===== SPECIALTIES ===== */
    .specialties { padding: 80px 0; background: var(--bg-light); }
    .section-header { text-align: center; max-width: 560px; margin: 0 auto 48px; }
    .section-header h2 {
      font-size: clamp(28px, 3.5vw, 36px); font-weight: 800;
      color: var(--text-primary); letter-spacing: -0.02em; margin-bottom: 12px;
    }
    .section-header p { font-size: 17px; color: var(--text-secondary); line-height: 1.6; }
    .specialties-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;
    }
    .specialty-card {
      background: #fff; border-radius: var(--radius-md);
      padding: 28px 24px; cursor: pointer;
      border: 1px solid var(--border);
      transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
      display: flex; align-items: flex-start; gap: 16px;
    }
    .specialty-card:hover {
      transform: translateY(-3px); box-shadow: var(--shadow-lg);
      border-color: var(--primary-light);
    }
    .specialty-card:active { transform: translateY(-1px); }
    .specialty-icon {
      width: 48px; height: 48px; border-radius: var(--radius-sm);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .specialty-icon svg { width: 24px; height: 24px; }
    .specialty-icon.primary-care { background: #DBEAFE; color: #2563EB; }
    .specialty-icon.dentist { background: #D1FAE5; color: #059669; }
    .specialty-icon.dermatologist { background: #FEE2E2; color: #DC2626; }
    .specialty-icon.psychiatrist { background: #EDE9FE; color: #7C3AED; }
    .specialty-icon.eye-doctor { background: #FEF3C7; color: #D97706; }
    .specialty-icon.orthopedic { background: #FFEDD5; color: #EA580C; }
    .specialty-info h3 { font-size: 17px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }
    .specialty-info p { font-size: 14px; color: var(--text-muted); line-height: 1.5; }

    /* ===== HOW IT WORKS ===== */
    .how-it-works { padding: 80px 0; background: var(--bg-white); }
    .steps-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px;
      position: relative;
    }
    .steps-grid::before {
      content: ''; position: absolute; top: 36px; left: 16.67%; right: 16.67%;
      height: 2px; background: var(--border);
    }
    .step { text-align: center; position: relative; }
    .step-number {
      width: 72px; height: 72px; border-radius: 50%;
      background: var(--primary); color: #fff;
      font-size: 24px; font-weight: 800;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 24px; position: relative; z-index: 1;
      box-shadow: 0 4px 12px rgba(37,99,235,0.25);
    }
    .step h3 { font-size: 18px; font-weight: 700; color: var(--text-primary); margin-bottom: 8px; }
    .step p { font-size: 15px; color: var(--text-secondary); line-height: 1.6; max-width: 320px; margin: 0 auto; }

    /* ===== TESTIMONIALS ===== */
    .testimonials { padding: 80px 0; background: var(--bg-light); }
    .testimonials-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
    }
    .testimonial-card {
      background: #fff; border-radius: var(--radius-md);
      padding: 32px 28px; border: 1px solid var(--border);
      display: flex; flex-direction: column;
      transition: box-shadow var(--transition);
    }
    .testimonial-card:hover { box-shadow: var(--shadow-lg); }
    .testimonial-stars {
      display: flex; gap: 2px; margin-bottom: 16px;
    }
    .testimonial-stars svg { width: 18px; height: 18px; color: #F59E0B; fill: #F59E0B; }
    .testimonial-text {
      font-size: 15px; line-height: 1.7; color: var(--text-secondary);
      flex: 1; margin-bottom: 20px; font-style: italic;
    }
    .testimonial-author { font-weight: 600; font-size: 15px; color: var(--text-primary); }
    .testimonial-location { font-size: 13px; color: var(--text-muted); margin-top: 2px; }

    /* ===== MOBILE APP PROMO ===== */
    .app-promo { padding: 80px 0; background: var(--bg-white); }
    .app-promo-inner {
      display: flex; align-items: center; gap: 64px;
      background: linear-gradient(135deg, var(--primary-50) 0%, var(--accent-light) 100%);
      border-radius: var(--radius-xl); padding: 64px; overflow: hidden;
      position: relative;
    }
    .app-promo-content { flex: 1; position: relative; z-index: 1; }
    .app-promo-content h2 {
      font-size: clamp(28px, 3.5vw, 36px); font-weight: 800;
      color: var(--text-primary); letter-spacing: -0.02em; margin-bottom: 12px;
    }
    .app-promo-content > p {
      font-size: 17px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 28px;
    }
    .app-features { list-style: none; display: flex; flex-direction: column; gap: 12px; margin-bottom: 32px; }
    .app-features li {
      display: flex; align-items: center; gap: 12px;
      font-size: 15px; color: var(--text-secondary);
    }
    .app-features li svg { width: 20px; height: 20px; color: var(--accent); flex-shrink: 0; }
    .app-buttons { display: flex; gap: 12px; flex-wrap: wrap; }
    .app-btn {
      display: inline-flex; align-items: center; gap: 10px;
      background: var(--text-primary); color: #fff;
      padding: 12px 20px; border-radius: var(--radius-md);
      font-size: 14px; font-weight: 600; cursor: pointer;
      border: none; font-family: inherit;
      transition: background var(--transition), transform 150ms ease;
    }
    .app-btn:hover { background: #0F172A; }
    .app-btn:active { transform: scale(0.97); }
    .app-btn svg { width: 24px; height: 24px; }
    .app-btn-text { text-align: left; line-height: 1.2; }
    .app-btn-text small { font-size: 11px; font-weight: 400; opacity: 0.8; display: block; }
    .app-btn-text strong { font-size: 15px; }

    .app-promo-visual {
      width: 280px; flex-shrink: 0;
      display: flex; align-items: center; justify-content: center;
      position: relative; z-index: 1;
    }
    .phone-mockup {
      width: 220px; height: 440px; background: var(--text-primary);
      border-radius: 32px; padding: 12px; position: relative;
      box-shadow: var(--shadow-xl);
    }
    .phone-screen {
      width: 100%; height: 100%; background: linear-gradient(180deg, var(--primary) 0%, var(--primary-dark) 100%);
      border-radius: 22px; overflow: hidden; display: flex; flex-direction: column;
      align-items: center; justify-content: center; gap: 16px; padding: 24px;
    }
    .phone-screen svg { width: 48px; height: 48px; color: #fff; opacity: 0.9; }
    .phone-screen span { color: #fff; font-weight: 700; font-size: 20px; }
    .phone-screen small { color: rgba(255,255,255,0.7); font-size: 13px; text-align: center; }
    .phone-notch {
      position: absolute; top: 12px; left: 50%; transform: translateX(-50%);
      width: 80px; height: 24px; background: var(--text-primary);
      border-radius: 0 0 14px 14px;
    }

    /* ===== FOOTER ===== */
    .footer { background: var(--text-primary); color: rgba(255,255,255,0.7); padding: 64px 0 32px; }
    .footer-grid {
      display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr 1fr; gap: 40px;
      margin-bottom: 48px;
    }
    .footer-brand p { font-size: 14px; line-height: 1.7; margin-top: 16px; max-width: 280px; }
    .footer-col h4 {
      font-size: 14px; font-weight: 700; color: #fff;
      text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a {
      font-size: 14px; color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }
    .footer-col a:hover { color: #fff; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px; display: flex; justify-content: space-between;
      align-items: center; flex-wrap: wrap; gap: 16px;
    }
    .footer-bottom p { font-size: 13px; }
    .footer-bottom-links { display: flex; gap: 24px; }
    .footer-bottom-links a { font-size: 13px; color: rgba(255,255,255,0.5); }
    .footer-bottom-links a:hover { color: #fff; }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1.5fr 1fr 1fr; }
      .footer-grid .footer-col:nth-child(4),
      .footer-grid .footer-col:nth-child(5) { grid-column: span 1; }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hamburger { display: flex; align-items: center; justify-content: center; }

      .hero { padding: 48px 0 64px; }
      .hero h1 { font-size: 32px; }
      .hero p { font-size: 16px; }

      .search-fields { flex-direction: column; }
      .search-field input,
      .search-field select { padding: 14px 16px 14px 44px; width: 100%; }
      .search-btn { width: 100%; justify-content: center; padding: 16px; }

      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .stat-number { font-size: 28px; }

      .specialties-grid { grid-template-columns: 1fr; }
      .specialties { padding: 56px 0; }

      .steps-grid { grid-template-columns: 1fr; gap: 40px; }
      .steps-grid::before { display: none; }
      .step-number { width: 56px; height: 56px; font-size: 20px; }
      .how-it-works { padding: 56px 0; }

      .testimonials-grid { grid-template-columns: 1fr; }
      .testimonials { padding: 56px 0; }

      .app-promo-inner { flex-direction: column; padding: 40px 24px; gap: 40px; text-align: center; }
      .app-promo-visual { width: 100%; }
      .app-features { align-items: center; }
      .app-buttons { justify-content: center; }

      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-brand { grid-column: span 2; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .hero { padding: 40px 0 48px; }
      .hero h1 { font-size: 28px; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
      .stat-item { padding: 12px; }
      .stat-number { font-size: 24px; }
      .stat-label { font-size: 13px; }
      .phone-mockup { width: 180px; height: 360px; }
    }

    /* Focus styles */
    a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible {
      outline: 2px solid var(--primary);
      outline-offset: 2px;
      border-radius: 4px;
    }
    .search-btn:focus-visible { outline-offset: 2px; }
  </style>
</head>
<body>
  <a href="#main" class="skip-link">Skip to main content</a>

  <!-- HEADER -->
  <header class="header" id="header">
    <div class="container header-inner">
      <a href="#" class="logo" aria-label="MedBook home">
        <svg viewBox="0 0 36 36" fill="none" xmlns="http://www.w3.org/2000/svg">
