  <script>
    // === HEADER SCROLL SHADOW ===
    const header = document.getElementById('header');
    let ticking = false;
    window.addEventListener('scroll', () => {
      if (!ticking) {
        requestAnimationFrame(() => {
          header.classList.toggle('scrolled', window.scrollY > 10);
          ticking = false;
        });
        ticking = true;
      }
    });

    // === MOBILE MENU ===
    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const drawerOverlay = document.getElementById('drawerOverlay');
    const drawerClose = document.getElementById('drawerClose');

    function openDrawer() {
      mobileDrawer.classList.add('open');
      drawerOverlay.classList.add('open');
      menuToggle.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
      drawerClose.focus();
    }
    function closeDrawer() {
      mobileDrawer.classList.remove('open');
      drawerOverlay.classList.remove('open');
      menuToggle.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      menuToggle.focus();
    }
    menuToggle.addEventListener('click', openDrawer);
    drawerClose.addEventListener('click', closeDrawer);
    drawerOverlay.addEventListener('click', closeDrawer);
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && mobileDrawer.classList.contains('open')) closeDrawer();
    });

    // === AUTOCOMPLETE ===
    const searchInput = document.getElementById('searchInput');
    const dropdown = document.getElementById('autocompleteDropdown');

    const suggestions = {
      specialties: ['Primary Care', 'Dentist', 'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon', 'Cardiologist', 'Pediatrician', 'OB/GYN', 'Endocrinologist'],
      conditions: ['Back pain', 'Headache', 'Skin rash', 'Anxiety', 'Sore throat', 'Knee pain', 'Acne', 'Depression', 'Allergies', 'Diabetes'],
      doctors: ['Dr. Sarah Chen', 'Dr. Michael Rivera', 'Dr. Emily Park', 'Dr. James Wilson', 'Dr. Lisa Nguyen']
